def db():
    s=SessionLocal()
    try: yield s
    finally: s.close()
def token_hash(x:str): return hashlib.sha256(x.encode()).hexdigest()
def current(request:Request, s:Session=Depends(db)):
    raw=request.cookies.get(os.getenv("SESSION_COOKIE_NAME","dsa_forge_session"))
    row=s.scalar(select(LoginSession).where(LoginSession.token_hash==token_hash(raw or ""),LoginSession.expires_at>datetime.utcnow()))
    if not row: raise HTTPException(401,"Authentication required")
    user=s.get(User,row.user_id)
    if user and user.role=="student" and user.approval_status!="Approved": raise HTTPException(403,"Student account is pending admin approval")
    return user
def slugify(title:str):
    base="".join(c.lower() if c.isalnum() else "-" for c in title).strip("-")[:180] or "question"; return f"{base}-{secrets.token_hex(4)}"
def visible(q:Question,s:Session):
    return {"id":q.id,"title":q.title,"slug":q.slug,"statement":q.statement,"difficulty":q.difficulty,"topic":q.topic,"tags":json.loads(q.tags),"constraints":q.constraints,"input_format":q.input_format,"output_format":q.output_format,"hints":q.hints,"editorial":q.editorial,"starter_code":json.loads(q.starter_code),"published":q.published,"created_at":q.created_at,"tests":[{"id":t.id,"input":t.input,"expected_output":t.expected_output} for t in s.scalars(select(TestCase).where(TestCase.question_id==q.id,TestCase.is_hidden==False))]}
def owned(q:Question,u:User): return q.owner_id==u.id
def progress_for(s,u,qid):
    p=s.scalar(select(Progress).where(Progress.user_id==u.id,Progress.question_id==qid))
    if not p: p=Progress(user_id=u.id,question_id=qid); s.add(p); s.flush()
    return p

@app.on_event("startup")
def seed():
    Base.metadata.create_all(engine)
    with engine.begin() as conn:
      columns = {column["name"] for column in inspect(conn).get_columns("users")}
      if "role" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN role VARCHAR(20) NOT NULL DEFAULT 'student'")
      if "registration_number" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN registration_number VARCHAR(64)")
      if "full_name" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN full_name VARCHAR(120)")
      if "year_of_study" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN year_of_study INTEGER")
      if "department_id" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN department_id INTEGER")
      if "section_id" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN section_id INTEGER")
      if "approval_status" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN approval_status VARCHAR(16) NOT NULL DEFAULT 'Approved'")
      if "faculty_code" not in columns: conn.exec_driver_sql("ALTER TABLE users ADD COLUMN faculty_code VARCHAR(40)")
      department_columns = {column["name"] for column in inspect(conn).get_columns("departments")}
      if "created_at" not in department_columns: conn.exec_driver_sql("ALTER TABLE departments ADD COLUMN created_at TIMESTAMP")
    with SessionLocal() as s:
      if not s.scalar(select(Department.id).limit(1)):
        for department_name in ("CSE","IT","ECE","EEE","MECH","AI&DS","CYBER"):
          department=Department(name=department_name); s.add(department); s.flush()
          s.add_all(AcademicSection(department_id=department.id,name=section_name) for section_name in ("A","B","C","D"))
        s.commit()
    with SessionLocal() as s:
      faculty_members=list(s.scalars(select(User).where(User.role=="faculty").order_by(User.id)))
      if faculty_members:
        reserved={code for code in s.scalars(select(User.faculty_code).where(User.faculty_code.is_not(None))) if code}
        seen=set(); next_number=1
        for member in faculty_members:
          code=(member.faculty_code or "").strip().upper()
          if not code or code in seen:
            while f"FAC-{next_number:03d}" in reserved or f"FAC-{next_number:03d}" in seen: next_number+=1
            code=f"FAC-{next_number:03d}"
          seen.add(code); reserved.add(code)
          if member.faculty_code!=code: member.faculty_code=code
        s.commit()
    with engine.begin() as conn:
      conn.exec_driver_sql("DELETE FROM faculty_students WHERE id NOT IN (SELECT MIN(id) FROM faculty_students GROUP BY student_id)")
      conn.exec_driver_sql("CREATE UNIQUE INDEX IF NOT EXISTS uq_faculty_students_student_id ON faculty_students (student_id)")
      conn.exec_driver_sql("CREATE UNIQUE INDEX IF NOT EXISTS ix_users_faculty_code ON users (faculty_code)")
    with SessionLocal() as s:
      admin_email=os.getenv("ADMIN_EMAIL","").strip().lower(); admin_password=os.getenv("ADMIN_PASSWORD","")
      if admin_email and admin_password:
        admin_user = s.scalar(select(User).where(User.email==admin_email))
        if not admin_user:
          s.add(User(email=admin_email,password_hash=password_hash.hash(admin_password),role="admin",approval_status="Approved"))
          s.commit()
        elif admin_user.role == "admin":
          admin_user.password_hash = password_hash.hash(admin_password)
          admin_user.approval_status = "Approved"
