@app.get("/api/health")
def health(): return {"status":"ok","executor":"docker" if _docker() else "unavailable"}
@app.post("/api/auth/register",status_code=201)
def register(body:Credentials,s:Session=Depends(db)):
    email=body.email.strip().lower()
    if s.scalar(select(User).where(User.email==email)): raise HTTPException(409,"Email already registered")
    registration_number=(body.registration_number or "").strip() or None
    if registration_number and s.scalar(select(User).where(User.registration_number==registration_number)): raise HTTPException(409,"Registration number already registered")
    u=User(email=email,password_hash=password_hash.hash(body.password),registration_number=registration_number,role="student",approval_status="Pending");s.add(u);s.commit();s.refresh(u)
    return {"id":u.id,"email":u.email,"role":u.role,"registration_number":u.registration_number,"approval_status":u.approval_status,"message":"Account created. An administrator must approve it before you can sign in."}
