# Academic role APIs
def require_role(user: User, *roles: str):
    if user.role not in roles: raise HTTPException(403, "This action is not permitted for your account role")
def empty_year_counts():
    return {"1":0,"2":0,"3":0,"4":0,"unset":0}
def add_year_count(counts: dict[str,int], year: int|None, count: int):
    counts["unset" if year is None or year not in (1,2,3,4) else str(year)] += count
def mentor_view(faculty: User):
    return {"id":faculty.id,"email":faculty.email,"full_name":faculty.full_name,"faculty_code":faculty.faculty_code}
def mentor_for_student(s: Session, student_id: int):
    faculty=s.scalar(select(User).join(FacultyStudent,FacultyStudent.faculty_id==User.id).where(FacultyStudent.student_id==student_id))
    return mentor_view(faculty) if faculty else None
def student_view(student: User, mentor: dict|None=None):
    return {"id":student.id,"email":student.email,"full_name":student.full_name,"role":student.role,"registration_number":student.registration_number,"year_of_study":student.year_of_study,"department_id":student.department_id,"department":{"id":student.department.id,"name":student.department.name} if student.department else None,"section_id":student.section_id,"section":{"id":student.section.id,"name":student.section.name} if student.section else None,"mentor":mentor,"approval_status":student.approval_status or "Approved","created_at":student.created_at}
def faculty_view(faculty: User, mentee_count: int=0, course_count: int=0):
    return {"id":faculty.id,"email":faculty.email,"full_name":faculty.full_name,"role":faculty.role,"faculty_code":faculty.faculty_code,"department_id":faculty.department_id,"department":{"id":faculty.department.id,"name":faculty.department.name} if faculty.department else None,"mentee_count":mentee_count,"course_count":course_count,"created_at":faculty.created_at}
def departments_view(departments: list[Department], s: Session):
    if not departments: return []
    department_ids=[department.id for department in departments]
    section_ids=[section.id for department in departments for section in department.sections]
    department_counts={department_id:empty_year_counts() for department_id in department_ids}
    section_counts={section_id:empty_year_counts() for section_id in section_ids}
    for department_id, year, count in s.execute(select(User.department_id,User.year_of_study,func.count()).where(User.department_id.in_(department_ids),User.role=="student").group_by(User.department_id,User.year_of_study)):
        add_year_count(department_counts[department_id],year,count)
    if section_ids:
        for section_id, year, count in s.execute(select(User.section_id,User.year_of_study,func.count()).where(User.section_id.in_(section_ids),User.role=="student").group_by(User.section_id,User.year_of_study)):
            add_year_count(section_counts[section_id],year,count)
    faculty_counts=dict(s.execute(select(User.department_id,func.count()).where(User.department_id.in_(department_ids),User.role=="faculty").group_by(User.department_id)).all())
    result=[]
    for department in departments:
        sections=[]
        for section in department.sections:
            counts=section_counts[section.id]
            sections.append({"id":section.id,"name":section.name,"student_count":sum(counts.values()),"year_counts":counts})
        counts=department_counts[department.id]
        result.append({"id":department.id,"name":department.name,"student_count":sum(counts.values()),"faculty_count":faculty_counts.get(department.id,0),"year_counts":counts,"sections":sections})
    return result
def department_view(department: Department, s: Session):
    return departments_view([department],s)[0]
def academic_ids(s: Session, department_id: int|None, section_id: int|None):
    section=s.get(AcademicSection,section_id) if section_id is not None else None
    if section_id is not None and not section: raise HTTPException(422,"Unknown section")
    if department_id is not None and not s.get(Department,department_id): raise HTTPException(422,"Unknown department")
    if section and department_id is not None and section.department_id!=department_id: raise HTTPException(422,"Selected section does not belong to the selected department")
    return department_id if department_id is not None else (section.department_id if section else None)
def clean_faculty_code(value: str|None):
    code=(value or "").strip().upper()
    if not code: raise HTTPException(422,"Faculty ID is required")
    if len(code)>40: raise HTTPException(422,"Faculty ID must be 40 characters or fewer")
    return code
def course_view(course: Course): return {"id":course.id,"title":course.title,"code":course.code,"description":course.description,"faculty_id":course.faculty_id,"active":course.active}
