@app.post("/api/admin/users",status_code=201)
def admin_create_user(body:AccountIn,u:User=Depends(current),s:Session=Depends(db)):
    require_role(u,"admin")
    email=body.email.strip().lower()
    if s.scalar(select(User).where(User.email==email)): raise HTTPException(409,"Email already registered")
    registration_number=(body.registration_number or "").strip() or None
    if registration_number and s.scalar(select(User).where(User.registration_number==registration_number)): raise HTTPException(409,"Registration number already registered")
    department_id=body.department_id; section_id=body.section_id; faculty_code=None
    if body.role=="student":
      department_id=academic_ids(s,body.department_id,body.section_id)
    elif body.role=="faculty":
      faculty_code=clean_faculty_code(body.faculty_code)
      if s.scalar(select(User).where(func.upper(User.faculty_code)==faculty_code)): raise HTTPException(409,"Faculty ID already exists")
      if department_id is not None and not s.get(Department,department_id): raise HTTPException(404,"Department not found")
      section_id=None
    else:
      department_id=None; section_id=None
    x=User(email=email,password_hash=password_hash.hash(body.password),role=body.role,registration_number=registration_number if body.role=="student" else None,full_name=(body.full_name or "").strip() or None,year_of_study=body.year_of_study if body.role=="student" else None,department_id=department_id,section_id=section_id,approval_status=body.approval_status if body.role=="student" else "Approved",faculty_code=faculty_code);s.add(x);s.commit();s.refresh(x)
    return student_view(x) if x.role=="student" else faculty_view(x)
@app.get("/api/admin/users")
def admin_users(search:str="",role:Literal["admin","faculty","student"]|None=None,year_of_study:int|None=None,year_unset:bool=False,department_id:int|None=None,section_id:int|None=None,status:str="",page:int=1,page_size:int=25,sort:str="newest",u:User=Depends(current),s:Session=Depends(db)):
    require_role(u,"admin")
    filters=[]
    if role: filters.append(User.role==role)
    term=search.strip().lower()
    if term:
        pattern=f"%{term}%"
        filters.append(or_(func.lower(User.email).like(pattern),func.lower(func.coalesce(User.full_name,"")).like(pattern),func.lower(func.coalesce(User.registration_number,"")).like(pattern)))
    if year_unset: filters.append(User.year_of_study.is_(None))
    elif year_of_study is not None: filters.append(User.year_of_study==year_of_study)
    if department_id is not None: filters.append(User.department_id==department_id)
    if section_id is not None: filters.append(User.section_id==section_id)
    if status: filters.append(User.approval_status==status)
    count_stmt=select(func.count()).select_from(User)
    if filters: count_stmt=count_stmt.where(*filters)
    total=s.scalar(count_stmt) or 0
    page=max(1,page);page_size=min(max(1,page_size),100)
    if sort=="name": order=[func.lower(func.coalesce(User.full_name,User.email)).asc()]
    elif sort=="oldest": order=[User.created_at.asc()]
    elif sort=="year": order=[case((User.year_of_study.is_(None),1),else_=0),User.year_of_study.asc(),func.lower(func.coalesce(User.full_name,User.email)).asc()]
    else: order=[User.created_at.desc()]
    stmt=select(User)
    if filters: stmt=stmt.where(*filters)
    rows=list(s.scalars(stmt.options(selectinload(User.department),selectinload(User.section)).order_by(*order).offset((page-1)*page_size).limit(page_size)))
    mentor_map={}
    if rows:
      mentor_rows=s.execute(select(FacultyStudent.student_id,User).join(User,User.id==FacultyStudent.faculty_id).where(FacultyStudent.student_id.in_([item.id for item in rows]))).all()
      mentor_map={student_id:mentor_view(faculty) for student_id,faculty in mentor_rows}
    return {"items":[student_view(x,mentor_map.get(x.id)) for x in rows],"total":total,"page":page,"page_size":page_size,"pages":max(1,(total+page_size-1)//page_size)}
