@app.patch("/api/admin/students/{student_id}")
def admin_update_student(student_id:int,body:StudentUpdate,u:User=Depends(current),s:Session=Depends(db)):
    require_role(u,"admin")
    student=s.get(User,student_id)
    if not student or student.role!="student": raise HTTPException(404,"Student not found")
    data=body.model_dump(exclude_unset=True)
    if data.get("approval_status") is None: data.pop("approval_status",None)
    password=data.pop("password",None)
    if "email" in data:
        email=(data["email"] or "").strip().lower()
        if not email: raise HTTPException(422,"Email is required")
        if s.scalar(select(User).where(User.email==email,User.id!=student_id)): raise HTTPException(409,"Email already registered")
        data["email"]=email
    if "registration_number" in data:
        registration_number=(data["registration_number"] or "").strip() or None
        if registration_number and s.scalar(select(User).where(User.registration_number==registration_number,User.id!=student_id)): raise HTTPException(409,"Registration number already registered")
        data["registration_number"]=registration_number
    if "full_name" in data: data["full_name"]=(data["full_name"] or "").strip() or None
    if "department_id" in data or "section_id" in data:
        department_id=data.get("department_id",student.department_id)
        section_id=data.get("section_id",student.section_id)
        if "department_id" in data and "section_id" not in data and section_id is not None:
            section=s.get(AcademicSection,section_id)
            if not section or section.department_id!=department_id:
                section_id=None;data["section_id"]=None
        department_id=academic_ids(s,department_id,section_id)
        data["department_id"]=department_id
        if "section_id" not in data: data["section_id"]=section_id
    for key,value in data.items(): setattr(student,key,value)
    if password:
        student.password_hash=password_hash.hash(password)
        s.execute(delete(LoginSession).where(LoginSession.user_id==student_id))
    s.commit();s.refresh(student)
    return student_view(student,mentor_for_student(s,student.id))
