@app.delete("/api/admin/students/{student_id}",status_code=204)
def admin_delete_student(student_id:int,u:User=Depends(current),s:Session=Depends(db)):
    require_role(u,"admin")
    student=s.get(User,student_id)
    if not student or student.role!="student": raise HTTPException(404,"Student not found")
    sheet_ids=list(s.scalars(select(Sheet.id).where(Sheet.owner_id==student_id)))
    if sheet_ids: s.execute(delete(SheetQuestion).where(SheetQuestion.sheet_id.in_(sheet_ids)))
    s.execute(delete(Sheet).where(Sheet.owner_id==student_id))
    s.execute(delete(Submission).where(Submission.user_id==student_id))
    s.execute(delete(Progress).where(Progress.user_id==student_id))
    s.execute(delete(Enrollment).where(Enrollment.student_id==student_id))
    s.execute(update(Enrollment).where(Enrollment.faculty_id==student_id).values(faculty_id=None))
    s.execute(delete(AssessmentAttempt).where(AssessmentAttempt.student_id==student_id))
    s.execute(delete(ProblemAssignment).where(or_(ProblemAssignment.student_id==student_id,ProblemAssignment.faculty_id==student_id)))
    s.execute(delete(FacultyStudent).where(or_(FacultyStudent.student_id==student_id,FacultyStudent.faculty_id==student_id)))
    s.execute(delete(LoginSession).where(LoginSession.user_id==student_id))
    s.execute(update(Question).where(Question.owner_id==student_id).values(owner_id=None))
    s.delete(student);s.commit()
