@app.post("/api/admin/faculty/{faculty_id}/mentees/range",status_code=201)
def admin_assign_mentees_range(faculty_id:int,body:MenteeRangeAssignmentIn,u:User=Depends(current),s:Session=Depends(db)):
    """Bulk assign students to a faculty member by registration-number range."""
    require_role(u,"admin")
    faculty=s.get(User,faculty_id)
    if not faculty or faculty.role!="faculty": raise HTTPException(404,"Faculty member not found")

    from_rn = (body.from_registration_number or "").strip()
    to_rn = (body.to_registration_number or "").strip()
    if not from_rn or not to_rn:
        raise HTTPException(422,"Both registration numbers are required")

    # Format-aware comparison: fixed-length numeric IDs use string comparison
    # (lexicographic order of equal-length digit strings equals numeric order)
    from_is_numeric = from_rn.isdigit()
    to_is_numeric = to_rn.isdigit()
    if from_is_numeric and to_is_numeric:
        if len(from_rn) != len(to_rn):
            raise HTTPException(422,"Registration numbers must have the same length for comparison")
        if from_rn > to_rn:
            raise HTTPException(422,"Starting registration number must be less than or equal to ending registration number")
        stmt = select(User).where(
            User.role=="student",
            User.registration_number >= from_rn,
            User.registration_number <= to_rn,
        )
    else:
        if from_rn > to_rn:
            raise HTTPException(422,"Starting registration number must be less than or equal to ending registration number")
        stmt = select(User).where(
            User.role=="student",
            User.registration_number >= from_rn,
            User.registration_number <= to_rn,
        )

    # Apply optional filters
    if body.department_id is not None:
        stmt = stmt.where(User.department_id == body.department_id)
    if body.year_of_study is not None:
        stmt = stmt.where(User.year_of_study == body.year_of_study)
    if body.section_id is not None:
        stmt = stmt.where(User.section_id == body.section_id)

    students = list(s.scalars(stmt.order_by(User.registration_number)))

    # Load existing mentor links for all matching students
    student_ids = [st.id for st in students]
    mentor_links = {}
    if student_ids:
        rows = s.execute(select(FacultyStudent.student_id, FacultyStudent.faculty_id).where(FacultyStudent.student_id.in_(student_ids))).all()
        mentor_links = {row[0]: row[1] for row in rows}

    # Load info for conflicting mentors
    conflict_faculty_ids = set(v for v in mentor_links.values() if v != faculty_id)
    conflict_faculty = {}
    if conflict_faculty_ids:
        rows = s.execute(select(User.id, User.faculty_code, User.full_name, User.email).where(User.id.in_(conflict_faculty_ids))).all()
        conflict_faculty = {row[0]: {"faculty_code": row[1], "full_name": row[2], "email": row[3]} for row in rows}

    assigned = 0
    skipped = 0
    conflicts = 0
    assigned_details = []
    skipped_details = []
    conflict_details = []

    if not body.preview:
        try:
            for student in students:
                existing_mentor_faculty_id = mentor_links.get(student.id)
                if existing_mentor_faculty_id == faculty_id:
                    skipped += 1
                    skipped_details.append({
                        "student_id": student.id,
                        "registration_number": student.registration_number,
                        "full_name": student.full_name,
                        "email": student.email,
                    })
                    continue
                if existing_mentor_faculty_id is not None:
                    conflicts += 1
                    conflict_details.append({
                        "student_id": student.id,
                        "registration_number": student.registration_number,
                        "full_name": student.full_name,
                        "email": student.email,
                        "current_mentor": conflict_faculty.get(existing_mentor_faculty_id, {}),
                    })
                    if body.reassign_conflicts:
                        s.execute(delete(FacultyStudent).where(FacultyStudent.student_id==student.id))
                        s.add(FacultyStudent(faculty_id=faculty_id, student_id=student.id))
                        assigned += 1
                        assigned_details.append({
                            "student_id": student.id,
                            "registration_number": student.registration_number,
                            "full_name": student.full_name,
                            "email": student.email,
                            "reassigned_from": conflict_faculty.get(existing_mentor_faculty_id, {}),
                        })
                    continue
                # No existing mentor: assign
                s.add(FacultyStudent(faculty_id=faculty_id, student_id=student.id))
                assigned += 1
                assigned_details.append({
                    "student_id": student.id,
                    "registration_number": student.registration_number,
                    "full_name": student.full_name,
                    "email": student.email,
                })
            s.commit()
        except Exception:
            s.rollback()
            raise
    else:
        # Preview mode: just compute what would happen, no DB changes
        for student in students:
            existing_mentor_faculty_id = mentor_links.get(student.id)
            if existing_mentor_faculty_id == faculty_id:
                skipped += 1
                skipped_details.append({
                    "student_id": student.id,
                    "registration_number": student.registration_number,
                    "full_name": student.full_name,
                    "email": student.email,
                })
                continue
            if existing_mentor_faculty_id is not None:
                conflicts += 1
                conflict_details.append({
                    "student_id": student.id,
                    "registration_number": student.registration_number,
                    "full_name": student.full_name,
                    "email": student.email,
                    "current_mentor": conflict_faculty.get(existing_mentor_faculty_id, {}),
                })
                continue
            # Would assign
            assigned += 1
            assigned_details.append({
                "student_id": student.id,
                "registration_number": student.registration_number,
                "full_name": student.full_name,
                "email": student.email,
            })

    return {
        "faculty_id": faculty_id,
        "faculty_code": faculty.faculty_code,
        "total_in_range": len(students),
        "total_matched": len(students),
        "assigned": assigned,
        "skipped": skipped,
        "conflicts": conflicts,
        "assigned_details": assigned_details,
        "skipped_details": skipped_details,
        "conflict_details": conflict_details,
    }

